import{_ as r,o as s,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const n="/assets/%E8%A3%B8%E6%9C%BA%E4%BA%91%E5%BC%80%E6%9C%BA11.fubBkjv0.png",a="/assets/%E8%A3%B8%E6%9C%BA%E4%BA%91%E5%85%B3%E6%9C%BA11.Bdwz-42T.png",e="/assets/%E8%A3%B8%E6%9C%BA%E4%BA%91%E9%87%8D%E5%90%AF11.C1Z3DLeG.png",g="/assets/%E7%A1%AC%E5%85%B3%E6%9C%BA.D_hoC9BO.png",l="/assets/%E7%A1%AC%E9%87%8D%E5%90%AF11.CDl-FgUv.png",E="/assets/%E9%87%8D%E7%BD%AE%E5%AF%86%E7%A0%8111.B2nxEVn4.png",p="data:image/png;base64,",h="/assets/%E9%87%8D%E8%A3%85%E7%B3%BB%E7%BB%9F12.CAnkX1aA.png",b=JSON.parse('{"title":"执行服务器操作","description":"","frontmatter":{"title":"执行服务器操作"},"headers":[],"relativePath":"baremetal/manage-baremetal/server-operations.md","filePath":"baremetal/manage-baremetal/server-operations.md","lastUpdated":1788259091000}'),A={name:"baremetal/manage-baremetal/server-operations.md"};function c(R,t,I,d,B,m){return s(),o("div",null,[...t[0]||(t[0]=[i('<p>在裸机云服务器<strong>管理产品</strong>页面，支持开机、关机、重启等操作。</p><hr><h3 id="开机" tabindex="-1">开机 <a class="header-anchor" href="#开机" aria-label="Permalink to &quot;开机&quot;">​</a></h3><p>服务器开机是指启动已关机的服务器。</p><ol><li><p>在裸机云<strong>管理产品</strong> -&gt; <strong>管理</strong>面板，单击<strong>开机</strong>。</p><p><img src="'+n+'" alt="裸机云开机11.png"></p></li><li><p>在开机确认页面单击<strong>确认</strong>。</p></li></ol><hr><h3 id="关机" tabindex="-1">关机 <a class="header-anchor" href="#关机" aria-label="Permalink to &quot;关机&quot;">​</a></h3><p>服务器关机是指关闭运行中的服务器。建议先通过远程连接保存数据。</p><ol><li>在裸机云<strong>管理产品</strong> -&gt; <strong>管理</strong>面板，单击<strong>关机</strong>。</li></ol><p><img src="'+a+'" alt="裸机云关机11.png"></p><ol start="2"><li>在关机确认页面单击<strong>确认</strong>。</li></ol><hr><h3 id="重启" tabindex="-1">重启 <a class="header-anchor" href="#重启" aria-label="Permalink to &quot;重启&quot;">​</a></h3><p>服务器重启是指将运行中的服务器关机并重新开机。适用于系统卡顿、配置生效等场景。</p><ol><li><p>在裸机云<strong>管理产品</strong> -&gt; <strong>管理</strong>面板，单击<strong>重启</strong>。</p><p><img src="'+e+'" alt="裸机云重启11.png"></p></li><li><p>在重启确认页面单击<strong>确认</strong>。</p></li></ol><hr><h3 id="硬关机" tabindex="-1">硬关机 <a class="header-anchor" href="#硬关机" aria-label="Permalink to &quot;硬关机&quot;">​</a></h3><p>硬关机等同于裸机云服务器直接断电，强制切断主机供电以关闭系统。</p><ol><li><p>在裸机云<strong>管理产品</strong> -&gt; <strong>管理</strong>面板，单击<strong>硬关机</strong>。</p><p><img src="'+g+'" alt="硬关机.png"></p></li><li><p>在硬关机确认页面单击<strong>确认</strong>。</p><blockquote><p><strong>注意</strong></p><ul><li>易导致未保存的业务数据丢失、文件系统损坏。</li><li>仅适用于系统卡死、软关机无响应的紧急场景。</li><li>操作后建议检查磁盘完整性。</li></ul></blockquote></li></ol><hr><h3 id="使用-vnc" tabindex="-1">使用 VNC <a class="header-anchor" href="#使用-vnc" aria-label="Permalink to &quot;使用 VNC&quot;">​</a></h3><p>使用 VNC 是指通过 VNC 远程连接服务器控制台。无需网络配置，直接访问系统界面。关于如何连接裸机云服务器的方法可参考使用裸机云服务器。</p><hr><h3 id="硬重启" tabindex="-1">硬重启 <a class="header-anchor" href="#硬重启" aria-label="Permalink to &quot;硬重启&quot;">​</a></h3><p>硬重启是指强制断电后立即通电重启主机，跳过系统正常关机流程，属于紧急重启方式。</p><ol><li><p>在裸机云<strong>管理产品</strong> -&gt; <strong>管理</strong>面板，单击<strong>硬重启</strong>。</p><p><img src="'+l+'" alt="硬重启11.png"></p></li><li><p>在硬重启确认页面单击<strong>确认</strong>。</p></li></ol><hr><h3 id="重置密码" tabindex="-1">重置密码 <a class="header-anchor" href="#重置密码" aria-label="Permalink to &quot;重置密码&quot;">​</a></h3><p>重置密码是指重置服务器的系统管理员密码，适用于密码遗忘或权限变更场景。</p><ol><li><p>在裸机云<strong>管理产品</strong> -&gt; <strong>管理</strong>面板，单击<strong>重置密码</strong>。</p><p><img src="'+E+'" alt="重置密码11.png"></p></li><li><p>在<strong>重置密码</strong>页面，输入修改后的密码。</p><p><img src="'+p+'" alt="密码重置成功1.png"></p><blockquote><p><strong>注意</strong> 当前操作需要实例在关机状态下进行：</p><ul><li>实例将关机中断您的业务，请仔细确认。</li><li>强制关机可能会导致数据丢失或文件系统损坏，您也可以主动关机后再进行操作。</li></ul></blockquote></li><li><p>单击<strong>确认</strong>。</p></li></ol><hr><h3 id="重装系统" tabindex="-1">重装系统 <a class="header-anchor" href="#重装系统" aria-label="Permalink to &quot;重装系统&quot;">​</a></h3><p>重装系统是指重新部署操作系统镜像，将服务器系统盘恢复至初始状态，常用于系统故障、更换系统版本或清理环境等场景，操作会格式化系统盘（数据盘通常不受影响，视配置而定）。</p><blockquote><p><strong>注意</strong> 重装会清除系统盘数据，请提前备份。</p></blockquote><ol><li><p>在裸机云<strong>管理产品</strong>-&gt;<strong>管理</strong>面板，单击<strong>重装系统</strong>。</p><p><img src="'+h+'" alt="重装系统12.png"></p></li><li><p>在<strong>重装系统</strong>页面，根据提示完成系统、登录方式和端口信息的选择和输入。</p></li><li><p>单击<strong>确认</strong>。</p></li></ol>',35)])])}const u=r(A,[["render",c]]);export{b as __pageData,u as default};
